window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9e2dc5fde9616865"]={"versions": [{"id": "FIG-9e2dc5fde9616865", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilprozesses innerhalb des AUTOSAR E2E-Protokolls (Profile 7). Es beschreibt den spezifischen Einzelschritt „Write Length“ im Rahmen der Schutz- und Weiterleitungsfunktionen <code>E2E_P07Protect()</code> und <code>E2E_P07Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitäts- bzw. Kontext-Symbole</strong>:</li>\n<li><code>E2E_P07Protect()</code>: Funktionskontext für den Schutz von Nutzdaten.</li>\n<li><code>E2E_P07Forward()</code>: Funktionskontext für das Weiterleiten geschützter Daten.</li>\n<li><strong>Aktion / Einzelschritt</strong>:</li>\n<li><code>Copy 4-byte Length on bytes Data[Offset+8...Offset+11] in Big Endian order</code>: Schreiboperation der Datenlänge in das Ziel-Array.</li>\n<li><strong>Knoten</strong>:</li>\n<li>Initialknoten (ausgefüllter schwarzer Kreis)</li>\n<li>Endknoten (Aktivitätsendknoten / Bullseye-Symbol)</li>\n<li><strong>Datenstrukturen / Parameter</strong>:</li>\n<li><code>Length</code>: 4-Byte-Längenwert (uint32).</li>\n<li><code>Data[]</code>: Byte-Array zur Aufnahme der serialisierten Protokolldaten.</li>\n<li><code>Offset</code>: Konfigurierter Basis-Offset im Datenpuffer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet am Initialknoten der Teilaktivität.</li>\n<li>Über einen unbedingten Kontrollfluss wird die Aktion <code>Copy 4-byte Length on bytes Data[Offset+8...Offset+11] in Big Endian order</code> ausgeführt. Dabei wird der 4-Byte-Längenwert ab Byteposition <code>Offset + 8</code> bis einschließlich <code>Offset + 11</code> im Big-Endian-Format (Most Significant Byte zuerst) in das Byte-Array <code>Data</code> geschrieben.</li>\n<li>Nach Abschluss der Schreiboperation führt die ausgehende Kante direkt zum Endknoten der Teilaktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das normative Verhalten für den Schritt „Write Length“ gemäß Anforderung <code>[PRS_E2E_00489]</code>. Implementierer von E2E Profile 7 müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\">\n<li>die Längenangabe exakt 4 Bytes belegt,</li>\n<li>die Zielposition im Datenarray strikt <code>Data[Offset+8]</code> bis <code>Data[Offset+11]</code> entspricht,</li>\n<li>die Serialisierung zwingend im Big-Endian-Format (Netzwerk-Byte-Reihenfolge) erfolgt, unabhängig von der nativen Prozessor-Endianness der ausführenden Plattform,</li>\n<li>die identische Logik sowohl in <code>E2E_P07Protect()</code> als auch in <code>E2E_P07Forward()</code> greift.</li>\n</ul>"}, {"id": "FIG-ff5fbfb8c90a083d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilprozesses innerhalb des AUTOSAR E2E-Protokolls (Profile 7). Es beschreibt den spezifischen Einzelschritt „Write Length“ im Rahmen der Schutz- und Weiterleitungsfunktionen <code>E2E_P07Protect()</code> und <code>E2E_P07Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitäts- bzw. Kontext-Symbole</strong>:</li>\n<li><code>E2E_P07Protect()</code>: Funktionskontext für den Schutz von Nutzdaten.</li>\n<li><code>E2E_P07Forward()</code>: Funktionskontext für das Weiterleiten geschützter Daten.</li>\n<li><strong>Aktion / Einzelschritt</strong>:</li>\n<li><code>Copy 4-byte Length on bytes Data[Offset+8...Offset+11] in Big Endian order</code>: Schreiboperation der Datenlänge in das Ziel-Array.</li>\n<li><strong>Knoten</strong>:</li>\n<li>Initialknoten (ausgefüllter schwarzer Kreis)</li>\n<li>Endknoten (Aktivitätsendknoten / Bullseye-Symbol)</li>\n<li><strong>Datenstrukturen / Parameter</strong>:</li>\n<li><code>Length</code>: 4-Byte-Längenwert (uint32).</li>\n<li><code>Data[]</code>: Byte-Array zur Aufnahme der serialisierten Protokolldaten.</li>\n<li><code>Offset</code>: Konfigurierter Basis-Offset im Datenpuffer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet am Initialknoten der Teilaktivität.</li>\n<li>Über einen unbedingten Kontrollfluss wird die Aktion <code>Copy 4-byte Length on bytes Data[Offset+8...Offset+11] in Big Endian order</code> ausgeführt. Dabei wird der 4-Byte-Längenwert ab Byteposition <code>Offset + 8</code> bis einschließlich <code>Offset + 11</code> im Big-Endian-Format (Most Significant Byte zuerst) in das Byte-Array <code>Data</code> geschrieben.</li>\n<li>Nach Abschluss der Schreiboperation führt die ausgehende Kante direkt zum Endknoten der Teilaktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das normative Verhalten für den Schritt „Write Length“ gemäß Anforderung <code>[PRS_E2E_00489]</code>. Implementierer von E2E Profile 7 müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\">\n<li>die Längenangabe exakt 4 Bytes belegt,</li>\n<li>die Zielposition im Datenarray strikt <code>Data[Offset+8]</code> bis <code>Data[Offset+11]</code> entspricht,</li>\n<li>die Serialisierung zwingend im Big-Endian-Format (Netzwerk-Byte-Reihenfolge) erfolgt, unabhängig von der nativen Prozessor-Endianness der ausführenden Plattform,</li>\n<li>die identische Logik sowohl in <code>E2E_P07Protect()</code> als auch in <code>E2E_P07Forward()</code> greift.</li>\n</ul>"}], "trans": [{"from": "FIG-9e2dc5fde9616865", "to": "FIG-ff5fbfb8c90a083d", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
